qss:
QWidget { background: #efe3c6; color: #3f3123; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #efe3c6; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #f7edd5; border: 1px solid #b99c76; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #3f3123; }
QLabel#SubtleLabel { color: #7b654b; }
QPushButton { background: #dfc89f; color: #3f3123; border: 1px solid #b99c76; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #d2b98b; }
QPushButton#AccentButton { background: #a65f28; border: 1px solid #bd7334; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #bd7334; }
QPushButton#DangerButton { background: #7f3e32; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #fff7e7; color: #3f3123; border: 1px solid #b99c76; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #ead0a1; border: 1px solid #a65f28; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #f7edd5; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #b99c76; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #b99c76; border-radius: 10px; background: #fff7e7; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #a65f28; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #f7edd5; border: 1px solid #b99c76; border-left: 4px solid #a65f28; border-radius: 16px; }
QFrame#UserBubbleCard { background: #ead0a1; border: 1px solid #b99c76; border-radius: 16px; }
